using System.Net.Http.Json;using DistributedMonolith.SharedContracts;
namespace DistributedMonolith.Orders.Infrastructure;
public sealed class UsersClient(HttpClient http){public async Task<bool> Exists(Guid id,CancellationToken ct){using var response=await http.GetAsync($"/internal/users/{id}/exists",ct);response.EnsureSuccessStatusCode();return await response.Content.ReadFromJsonAsync<bool>(ct) ?? false;}}
public sealed class ProductsClient(HttpClient http){public async Task<ProductResponse?> Get(Guid id,CancellationToken ct){using var response=await http.GetAsync($"/api/products/{id}",ct);if(response.StatusCode==System.Net.HttpStatusCode.NotFound)return null;response.EnsureSuccessStatusCode();return await response.Content.ReadFromJsonAsync<ProductResponse>(ct);}public async Task<StockReservationResponse> Reserve(Guid id,int quantity,CancellationToken ct){using var response=await http.PostAsJsonAsync($"/internal/products/{id}/reserve",new StockReservationRequest(quantity),ct);response.EnsureSuccessStatusCode();return (await response.Content.ReadFromJsonAsync<StockReservationResponse>(ct))!;}}
